import { chromium } from 'playwright';

const username = process.env.LOGIN_USERNAME;
const password = process.env.LOGIN_PASSWORD;

if (!username || !password) {
  throw new Error('Set LOGIN_USERNAME and LOGIN_PASSWORD before running this script.');
}

const browser = await chromium.launch({ headless: false });
try {
  const page = await browser.newPage();
  await page.goto('http://localhost:5173');

  // Open the login form. Change the accessible name here if the button uses
  // different text in the app.
  await page.getByRole('button', { name: /登录|log\s*in|sign\s*in/i }).click();

  // Prefer accessible labels; adjust these selectors if the form has no labels.
  await page.getByLabel(/用户名|账号|username|email/i).fill(username);
  await page.getByLabel(/密码|password/i).fill(password);
  await page.getByRole('button', { name: /登录|提交|log\s*in|sign\s*in|submit/i }).click();
} finally {
  await browser.close();
}
